Certainly! Below is an example of how you might implement a Contextual Multi-Armed Bandit (CMAB) algorithm using Object-Oriented Programming (OOP) principles in Python. This implementation will use three different models to make decisions based on the context.

```python
import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def __init__(self):
        super().__init__()

    def fit(self, X, y):
        # Simple linear regression with least squares
        self.weights = np.linalg.inv(X.T @ X) @ X.T @ y

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def __init__(self):
        super().__init__()

    def fit(self, X, y):
        pass

    def predict(self, X):
        return np.random.rand(len(X))

class EpsilonGreedyBandit:
    def __init__(self, models, epsilon=0.1):
        self.models = models
        self.epsilon = epsilon
        self.rewards = {model: [] for model in models}
        self.contexts = []
        self.actions = []

    def select_action(self, context):
        if np.random.rand() < self.epsilon:
            action = np.random.choice(len(self.models))
        else:
            predictions = [model.predict([context])[0] for model in self.models]
            action = np.argmax(predictions)

        self.contexts.append(context)
        self.actions.append(action)
        return action

    def update(self, action, reward):
        self.rewards[self.models[action]].append(reward)

# Example usage
if __name__ == "__main__":
    # Generate some synthetic data
    n_samples = 1000
    n_features = 5
    contexts = np.random.rand(n_samples, n_features)
    rewards = np.random.randint(0, 2, size=n_samples)

    # Initialize models
    models = [LinearModel(), RandomModel(), LinearModel()]

    # Initialize bandit
    bandit = EpsilonGreedyBandit(models=models, epsilon=0.1)

    # Run the bandit
    for i in range(n_samples):
        action = bandit.select_action(contexts[i])
        reward = rewards[i]
        bandit.update(action, reward)

    # Print results
    print("Rewards per model:")
    for model, rewards_list in bandit.rewards.items():
        print(f"Model: {model}, Average Reward: {np.mean(rewards_list)}")
```

### Explanation:
1. **Model Class**: A base class that defines the interface for all models.
2. **LinearModel Class**: Implements a simple linear regression model.
3. **RandomModel Class**: Implements a random model that always returns a random prediction.
4. **EpsilonGreedyBandit Class**: Implements the ε-greedy strategy for selecting actions and updating rewards.
5. **Example Usage**: Generates synthetic data, initializes the models and bandit, runs the bandit over the data, and prints the average rewards for each model.

This code provides a basic framework for implementing a CMAB algorithm with multiple models. You can extend it by adding more sophisticated models or strategies as needed.

