```c
#include <stdio.h>
#include <stdlib.h>

// Simple reverb algorithm using delay lines
void apply_reverb(float* input, float* output, int length, float decay) {
    static const int num_delays = 5;
    static float delays[num_delays][length];
    static int delay_indices[num_delays];

    for (int i = 0; i < length; ++i) {
        // Apply feedback loop with decay factor
        float sum = input[i] * decay;
        for (int j = 0; j < num_delays; ++j) {
            if (delay_indices[j] >= 0) {
                sum += delays[j][delay_indices[j]];
            }
        }

        // Update output buffer
        output[i] = sum;

        // Store current sample in all delay lines
        for (int j = 0; j < num_delays; ++j) {
            delays[j][delay_indices[j]] = input[i];
            delay_indices[j]++;
            if (delay_indices[j] >= length) {
                delay_indices[j] = 0;
            }
        }
    }
}
```

2. **Compile the C/C++ code into a shared library**:

On Linux:
