        <div className="p-4">{children}</div>
      </main>
    </div>
  );
};

export default Layout;
```

In this code:

- We use the `useState` hook to manage the state of whether the sidebar is open or closed.
- On mobile devices, we show a hamburger icon which toggles the visibility of the sidebar.
- On larger screens, the sidebar is always visible without any interaction needed.

Finally, wrap your pages with the `Layout` component in `_app.js`:

```jsx
// pages/_app.js
import '../styles/globals.css';
import Layout from '../components/Layout';

function MyApp({ Component, pageProps }) {
  return (
    <Layout>
      <Component {...pageProps} />
    </Layout>
  );
}

export default MyApp;
```

This setup ensures that your application has a responsive navigation bar that adapts to different screen sizes.

Certainly! Below is a simple implementation of the Connect-4 game in Python. This version allows two players to take turns dropping their pieces into the board, and it checks for a win after each move.

```python
def print_board(board):
    for row in board:
        print(" | ".join(row))
        print("-" * 9)

def check_win(board, player):
    # Check horizontal locations for win
    for row in range(6):
        for col in range(4):
            if board[row][col] == player and board[row][col+1] == player and board[row][col+2] == player and board[row][col+3] == player:
                return True

    # Check vertical locations for win
    for row in range(3):
        for col in range(7):
            if board[row][col] == player and board[row+1][col] == player and board[row+2][col] == player and board[row+3][col] == player:
                return True

    # Check positively sloped diagonals
    for row in range(3):
        for col in range(4):
            if board[row][col] == player and board[row+1][col+1] == player and board[row+2][col+2] == player and board[row+3][col+3] == player:
                return True

    # Check negatively sloped diagonals
    for row in range(3, 6):
        for col in range(4):
            if board[row][col] == player and board[row-1][col+1] == player and board[row-2][col+2] == player and board[row-3][col+3] == player:
                return True

    return False

def is_full(board):
    for row in board:
        if " " in row:
            return False
    return True

def main():
    board = [[" " for _ in range(7)] for _ in range(6)]
    current_player = "X"

    while True:
        print_board(board)
        print(f"Player {current_player}'s turn")

        try:
            column = int(input("Choose a column (0-6): "))
            if column < 0 or column > 6:
                print("Invalid column. Please choose between 0 and 6.")
                continue

            for row in range(5, -1, -1):
                if board[row][column] == " ":
                    board[row][column] = current_player
                    break
            else:
                print("Column is full. Try again.")
                continue

            if check_win(board, current_player):
                print_board(board)
                print(f"Player {current_player} wins!")
                break

            if is_full(board):
                print_board(board)
                print("It's a draw!")
                break

            current_player = "O" if current_player == "X" else "X"

        except ValueError:
            print("Please enter a valid number.")

if __name__ == "__main__":
    main()
```

### How to Play:
1. Run the program.
2. Players take turns entering a column number (0-6) where they want to drop their piece.
3. The game will automatically check for a win or a draw after each move.
4. The first player to get four of their pieces in a row (horizontally, vertically, or diagonally) wins!

### Notes:
- The board is represented as a 6x7 grid.
- The game alternates between two players, "X" and "O".
- The game ends when there is a winner or when the board is full (a draw).

Enjoy playing Connect-4!

